import { describe, expect, test } from "bun:test";
import { subtotal, total, TAX_RATE, type Line } from "./invoice";

describe("subtotal", () => {
  test("sums lines with no discount when quantity is below 10", () => {
    const lines: Line[] = [
      { description: "Widget", unitCents: 500, quantity: 9 },
      { description: "Gadget", unitCents: 200, quantity: 3 },
    ];
    expect(subtotal(lines)).toBe(500 * 9 + 200 * 3);
  });

  test("applies 5% off a line whose quantity is exactly 10", () => {
    const lines: Line[] = [{ description: "Widget", unitCents: 100, quantity: 10 }];
    // 100 * 10 = 1000, 5% off = 950
    expect(subtotal(lines)).toBe(950);
  });

  test("applies 5% off a line whose quantity is above 10", () => {
    const lines: Line[] = [{ description: "Widget", unitCents: 100, quantity: 12 }];
    // 100 * 12 = 1200, 5% off = 1140
    expect(subtotal(lines)).toBe(1140);
  });

  test("does not discount a line with quantity 9 (boundary check)", () => {
    const lines: Line[] = [{ description: "Widget", unitCents: 100, quantity: 9 }];
    expect(subtotal(lines)).toBe(900);
  });

  test("discounts only qualifying lines when mixed with non-qualifying lines", () => {
    const lines: Line[] = [
      { description: "Widget", unitCents: 100, quantity: 10 }, // discounted: 950
      { description: "Gadget", unitCents: 200, quantity: 3 }, // not discounted: 600
    ];
    expect(subtotal(lines)).toBe(950 + 600);
  });

  test("rounds fractional cent discounts to the nearest cent", () => {
    const lines: Line[] = [{ description: "Widget", unitCents: 99, quantity: 10 }];
    // 99 * 10 = 990, 5% off = 940.5 -> rounds to 941
    expect(subtotal(lines)).toBe(941);
  });

  test("returns 0 for an empty invoice", () => {
    expect(subtotal([])).toBe(0);
  });
});

describe("total", () => {
  test("applies tax on top of the discounted subtotal", () => {
    const lines: Line[] = [{ description: "Widget", unitCents: 100, quantity: 10 }];
    const discountedSubtotal = 950;
    expect(total(lines)).toBe(Math.round(discountedSubtotal * (1 + TAX_RATE)));
  });

  test("matches subtotal-based tax calculation for mixed lines", () => {
    const lines: Line[] = [
      { description: "Widget", unitCents: 100, quantity: 10 },
      { description: "Gadget", unitCents: 200, quantity: 3 },
    ];
    expect(total(lines)).toBe(Math.round(subtotal(lines) * (1 + TAX_RATE)));
  });
});

